package career.assistant.application.controller;
import career.assistant.application.service.ApplicationWorkflowService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotNull; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/applications") public class ApplicationController {private final ApplicationWorkflowService service;public ApplicationController(ApplicationWorkflowService s){service=s;}@GetMapping public List<ApplicationWorkflowService.WorkflowResponse> list(){return service.list();}@PostMapping("/packages")public ResponseEntity<ApplicationWorkflowService.WorkflowResponse> generate(@Valid @RequestBody GenerateRequest r){return ResponseEntity.status(201).body(service.generate(r.jobId(),r.lowConfidenceConfirmed()));}@PatchMapping("/{id}/review")public ApplicationWorkflowService.WorkflowResponse review(@PathVariable UUID id,@Valid @RequestBody ReviewRequest r){return service.review(id,r.approve(),r.reason());}@PostMapping("/{id}/run")public ApplicationWorkflowService.WorkflowResponse run(@PathVariable UUID id){return service.run(id);}public record GenerateRequest(@NotNull UUID jobId,boolean lowConfidenceConfirmed){}public record ReviewRequest(boolean approve,String reason){}}
